<script setup>
import { assetUrl } from '../lib/assets.js'
import { ref,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowRight,Info,Star,AlertTriangle } from 'lucide-vue-next'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { state,taskById,addOrder,money } from '../lib/store'
import { confirm,notify,requireRole } from '../lib/actions'
const route=useRoute(),router=useRouter(),sort=ref('推荐排序'),detail=ref(null),winning=ref('')
const task=computed(()=>taskById(route.query.task||'square-8'))
const candidates=computed(()=>{const base=[{name:'林间设计',level:'Lv.3 认证',rate:98,orders:36,response:'20 分钟',quote:Math.min(task.value?.price||980,900),days:3,description:'先统一模特与光线，再匹配服装细节。保证构图一致、材质自然，并提供两轮精修。'},{name:'小野视觉',level:'Lv.2 进阶',rate:97,orders:28,response:'30 分钟',quote:task.value?.price||980,days:3,description:'采用自然光影与简约场景，突出秋冬服装的质感、版型及日常穿搭氛围。'},{name:'木白创作',level:'Lv.1 见习',rate:98,orders:12,response:'1 小时',quote:Math.min(task.value?.price||980,500),days:3,description:'按需求完成模特换装与场景制作，交付高清成品，支持根据反馈细化画面。'}];if(sort.value==='报价最低')base.sort((a,b)=>a.quote-b.quote);if(sort.value==='好评率最高')base.sort((a,b)=>b.rate-a.rate||b.orders-a.orders);return base})
const canChoose=computed(()=>task.value?.status==='招募中'&&!winning.value)
async function choose(c){if(!canChoose.value||!requireRole(router,'merchant',true))return;if(await confirm(`确定选择 ${c.name}？报价 ¥${c.quote}，${c.days} 天交付。演示中标后将创建订单，其余投标结束。`,'确认中标创作者')){const o=addOrder(task.value,c.quote*100,c.name);winning.value=c.name;state.bids.filter(b=>b.taskId===task.value.id).forEach(b=>b.status=c.name===state.session.nickname?'已中标':'未中标');notify('演示中标成功，任务已进入进行中');router.push('/merchant/tasks?status=进行中')}}
</script>
<template><div><PageTitle title="选择合适的创作者" description="比较方案与作品，找到适合这份需求的人。"/><div class="panel bid-context"><el-select :model-value="task?.id" @change="router.push(`/merchant/bids?task=${$event}`)" aria-label="选择比稿任务"><el-option v-for="t in state.tasks.filter(t=>t.mode==='比稿')" :key="t.id" :label="t.title" :value="t.id"/></el-select><span>预算 <strong class="price-text">¥{{task?.price}}</strong></span><StatusBadge :status="task?.status||'招募中'"/></div><div class="inline-actions" style="margin:20px 0"><span>排序：</span><el-select v-model="sort" style="width:150px" aria-label="投标排序"><el-option v-for="s in ['推荐排序','报价最低','好评率最高']" :key="s" :value="s"/></el-select><span class="muted small">查看作品、报价与交付计划</span></div><div class="info-note" style="margin-bottom:18px"><Info/>中标后锁定赏金，其余投标自动结束。{{canChoose?'选人需要二次确认。':'该任务当前不可继续选人。'}}</div><div class="candidate-grid"><section v-for="(c,i) in candidates" :key="c.name" :class="['panel candidate-card',{recommended:c.name==='林间设计'}]"><div v-if="c.name==='林间设计'" class="recommend-label"><Star :size="12"/>推荐</div><div class="person"><img class="avatar" src="/assets/pages/creator-avatar.webp" :alt="c.name+'示例头像'"/><div><h3>{{c.name}}</h3><span class="plain-tag">{{c.level}}</span></div></div><div class="candidate-metrics"><div>好评率<strong>{{c.rate}}%</strong></div><div>成单<strong>{{c.orders}}</strong></div><div>响应<strong>{{c.response}}</strong></div></div><div class="candidate-quote"><div>报价<strong class="price-text">¥{{money(c.quote*100)}}</strong></div><div>预计交付<strong>{{c.days}} 天</strong></div></div><h3>作品示例（3 张）</h3><div class="candidate-portfolio"><el-image v-for="j in 3" :key="j" :src="assetUrl(`pages/fashion-${j}.webp`)" :preview-src-list="[1,2,3].map(n=>assetUrl(`pages/fashion-${n}.webp`))" :initial-index="j-1" preview-teleported :alt="c.name+'作品示例'"/></div><h3>投标方案</h3><p class="proposal-summary">{{c.description}}</p><div v-if="c.level.includes('见习')" class="info-note warning"><AlertTriangle/>新手创作者，请仔细核对作品与方案。</div><div class="candidate-bottom"><el-button link type="primary" @click="detail=c">查看完整方案<ArrowRight/></el-button><el-button class="full-button" type="primary" :disabled="!canChoose" @click="choose(c)">选 TA 中标</el-button></div></section></div><el-dialog :model-value="!!detail" :title="detail?.name+' · 完整方案'" width="590px" @close="detail=null" class="refinement-dialog"><div v-if="detail" class="app-ui dialog-stack"><p>{{detail.description}}</p><p>交付计划：第一天确定风格与构图；第二天完成主体细节；第三天统一精修并提交验收。支持任务约定的免费修改轮次。</p><div class="info-note">报价 ¥{{detail.quote}} · 工期 {{detail.days}} 天 · 以上为演示方案</div></div><template #footer><el-button @click="detail=null">关闭</el-button><el-button type="primary" :disabled="!canChoose" @click="choose(detail)">选择这位创作者</el-button></template></el-dialog></div></template>
<style scoped>.bid-context{display:flex;gap:24px;align-items:center;padding:16px 20px}.bid-context .el-select{width:380px;max-width:70%}.candidate-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.candidate-card{margin:0!important;position:relative;padding:26px 18px 18px;display:flex;flex-direction:column;min-width:0}.candidate-card.recommended{border-color:#002bd7;border-width:2px;padding:25px 17px 17px}.recommend-label{position:absolute;top:-1px;left:-1px;display:flex;gap:6px;align-items:center;background:#002bd7;color:#fff;padding:3px 14px;border-radius:6px 0 6px 0;font-size:11px}.candidate-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;text-align:center;font-size:11px;color:#737d8e;margin:24px 0 15px}.candidate-metrics strong{display:block;font-size:18px;color:#171b24;margin-top:4px}.candidate-quote{display:flex;justify-content:space-between;border-top:1px solid #e8ecf3;border-bottom:1px solid #e8ecf3;padding:15px 0;margin-bottom:18px;font-size:12px}.candidate-quote strong{display:block;font-size:23px}.candidate-quote>div:last-child strong{font-size:20px}.candidate-portfolio{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:16px}.candidate-portfolio .el-image{width:100%;aspect-ratio:1;border-radius:5px;overflow:hidden}.proposal-summary{font-size:12px;line-height:1.9;color:#596476;min-height:88px}.candidate-card .info-note{padding:7px 8px;font-size:10px}.candidate-bottom{margin-top:auto;display:flex;flex-direction:column;align-items:flex-start;gap:15px;padding-top:12px}@media(max-width:1100px){.candidate-grid{gap:12px}.candidate-card{padding:26px 12px 14px}.candidate-card.recommended{padding:25px 11px 13px}.candidate-card .person{flex-wrap:wrap}.candidate-metrics strong{font-size:16px}.candidate-quote strong{font-size:19px}}@media(max-width:950px){.candidate-grid{grid-template-columns:1fr}.candidate-card .person{flex-wrap:nowrap}.candidate-portfolio{max-width:420px}.proposal-summary{min-height:0}.bid-context{flex-wrap:wrap;gap:12px}.bid-context .el-select{max-width:100%}}</style>
